public str getName()
{
    return fieldPName(InventDim, InventVersionId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    EcoResVersion version;
    while select Name from version
        group by Name
    {
        ret.add(version.Name);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventVersionId));
    qbr.value(queryValue(_value));
}
